em .meta{padding:10px}.name{font-size:12px;font-weight:750;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.size{font-size:10px;color:var(--muted);margin-top:3px}.remove{position:absolute;right:8px;top:8px;width:32px;height:32px;border:0;border-radius:9px;background:#fff;box-shadow:0 4px 15px #17203325;cursor:pointer}.actions{display:none;gap:9px;margin-top:16px}.process{flex:1;background:var(--p);color:#fff}.result{display:none;margin-top:18px}.status{padding:12px 14px;border-radius:12px;background:#f1efff;color:#5147cc;font-size:12px;margin-bottom:12px}.out-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:14px}.out{padding:12px;border:1px solid var(--line);border-radius:15px;background:#fff}.out img{width:100%;height:220px;object-fit:contain;background:repeating-conic-gradient(#eee 0 25%,#fff 0 50%) 50%/18px 18px;border-radius:10px}.out .btn{display:block;text-align:center;background:var(--p);color:#fff;margin-top:9px;width:100%}.note{text-align:center;color:var(--muted);font-size:11px;margin-top:15px}@media(max-width:560px){.card{padding:14px}.drop{min-height:210px}.item img{height:145px}}
