<div class="result" id="result"><div class="status" id="status"></div><div class="out-grid" id="outputs"></div></div><div class="note">Your source images stay in your browser while the background-removal model runs.</div></section></main>
<script type="module">
import { removeBackground } from 'https://cdn.jsdelivr.net/npm/@imgly/background-removal@1.7.0/+esm';
const picker=document.getElementById('picker'),drop=document.getElementById('drop'),grid=document.getElementById('grid'),preview=document.getElementById('preview'),actions=document.getElementById('actions'),count=document.getElementById('count'),result=document.getElementById('result'),status=document.getElementById('status'),outputs=document.getElementById('outputs');let files=[];
function esc(s){return s.replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}function size(n){return n<1048576?(n/1024).toFixed(1)+' KB':(n/1048576).toFixed(2)+' MB'}
function add(fs){files.push(...[...fs].filter(f=>/^image\/(png|jpeg|webp)$/.test(f.type)));render()}
function render(){grid.innerHTML='';count.textContent=files.length+' image'+(files.length===1?'':'s')+' selected';preview.style.display=files.length?'block':'none';actions.style.display=files.length?'flex':'none';files.forEach((f,i)=>{const u=URL.createObjectURL(f),d=document.createElement('div');d.className='item';d.innerHTML='<img src="'+u+'" alt=""><button class="remove" aria-label="Remove '+esc(f.name)+'">🗑️</button><div class="meta"><div class="name">'+esc(f.name)+'</div><div class="size">'+size(f.size)+'</div></div>';d.querySelector('.remove').onclick=()=>{URL.revokeObjectURL(u);files.splice(i,1);render()};grid.appendChild(d)})}
picker.onchange=e=>{add(e.target.files);picker.value=''};['dragenter','dragover'].forEach(x=>drop.addEventListener(x,e=>{e.preventDefault();drop.classList.add('drag')}));['dragleave','drop'].forEach(x=>drop.addEventListener(x,e=>{e.preventDefault();drop.classList.remove('drag')}));drop.addEventListener('drop',e=>add(e.dataTransfer.files));document.getElementById('clear').onclick=()=>{files=[];render();result.style.display='none'};
document.getElementById('process').onclick=async()=>{if(!files.length)return;const btn=document.getElementById('process');btn.disabled=true;outputs.innerHTML='';result.style.display='block';for(let i=0;i<files.length;i++){status.textContent='Removing background: '+(i+1)+' / '+files.length+'…';try{const blob=await removeBackground(files[i],{output:{format:'image/png',quality:1}});const url=URL.createObjectURL(blob),name=files[i].name.replace(/\.[^.]+$/,'')+'-no-background.png';const d=document.createElement('div');d.className='out';d.innerHTML='<img src="'+url+'" alt=""><div class="name" style="margin-top:8px">'+esc(name)+'</div><a class="btn" href="'+url+'" download="'+esc(name)+'">⬇ Download PNG</a>';outputs.appendChild(d)}catch(e){const d=document.createElement('div');d.className='status';d.textContent='Could not process '+files[i].name+': '+(e?.message||e);outputs.appendChild(d)}}status.textContent='Done — '+files.length+' image'+(files.length===1?'':'s')+' processed.';btn.disabled=false};
</script></body></html>